$_LANG['domaingeteppcodeexplanation'] = "ໂດຍພື້ນຖານແລ້ວລະຫັດ EPP ແມ່ນລະຫັດຜ່ານສຳລັບຊື່ໂດເມນ. ມັນແມ່ນມາດຕະການຄວາມປອດໄພ, ເພື່ອຮັບປະກັນວ່າມີພຽງແຕ່ເຈົ້າຂອງຊື່ໂດເມນເທົ່ານັ້ນທີ່ສາມາດຍ້າຍຊື່ໂດເມນໄດ້. ທ່ານຈະຕ້ອງການມັນຫາກທ່ານຕ້ອງການຍ້າຍໂດເມນໄປຫາຜູ້ໃຫ້ບໍລິການອື່ນ.";
