$_LANG['maxmind_callingnow'] = "ພວກເຮົານຳກຳລັງໂທຫາເບີໂທລະສັບຂອງທ່ານແບບອັດຕະໂນມັດໃນຕອນນີ້. ນີ້ແມ່ນສ່ວນໜຶ່ງຂອງມາດຕະການກວດສອບການສໍ້ໂກງຂອງພວກເຮົາ. ທ່ານຈະໄດ້ຮັບລະຫັດຄວາມປອດໄພ 4 ຫຼັກ ເຊິ່ງທ່ານຕ້ອງປ້ອນໃສ່ດ້ານລຸ່ມເພື່ອໃຫ້ການສັ່ງຊື້ສຳເລັດ.";
