$_LANG['maxmind_error'] = "ຂໍ້ຜິດພາດ";
$_LANG['maxmind_faileddescription'] = "ລະຫັດທີ່ທ່ານປ້ອນບໍ່ຖືກຕ້ອງ. ຫາກທ່ານຄິດວ່ານີ້ຄືຂໍ້ຜິດພາດ, ກະລຸນາຕິດຕໍ່ພະແນກຊ່ວຍເຫຼືອຂອງພວກເຮົາໂດຍໄວທີ່ສຸດ.";
$_LANG['maxmind_highfraudriskscore'] = "ຄຳສັ່ງຊື້ຂອງທ່ານຖືກລະບຸວ່າມີຄວາມສ່ຽງສູງ ດັ່ງນັ້ນຈຶ່ງຖືກລະງັບໄວ້ເພື່ອລໍຖ້າການກວດສອບດ້ວຍຕົນເອງ.<br /><br />ຫາກທ່ານຄິດວ່າໄດ້ຮັບຂໍ້ຄວາມນີ້ຍ້ອນຄວາມຜິດພາດ, ກະລຸນາຮັບຄຳຂໍໂທດຈາກພວກເຮົາ ແລະ <a href=\"submitticket.php\">ສົ່ງປີ້ຊ່ວຍເຫຼືອ</a> ຫາທີມງານບໍລິການລູກຄ້າຂອງພວກເຮົາ. ຂອບໃຈ.";
$_LANG['maxmind_highriskcountry'] = "ຂໍອະໄພ, ພວກເຮົາບໍ່ສາມາດຮັບຄຳສັ່ງຊື້ຂອງທ່ານໄດ້ ເນື່ອງຈາກມີກິດຈະກຳການສໍ້ໂກງຈຳນວນຫຼາຍຈາກປະເທດຂອງທ່ານ. ຫາກທ່ານຕ້ອງການຊຳລະເງິນດ້ວຍຊ່ອງທາງອື່ນ, ກະລຸນາຕິດຕໍ່ພວກເຮົາ.";
