$_LANG['upgradeproductlogic'] = "ລາຄາອັບເກຣດແມ່ນຄິດໄລ່ຈາກຍອດເງິນຄືນຂອງສ່ວນທີ່ຍັງບໍ່ໄດ້ໃຊ້ຂອງແຜນປັດຈຸບັນ ແລະ ການເກັບເງິນຂອງແຜນໃໝ່ສຳລັບໄລຍະເວລາດຽວກັນ";
