$_LANG['varilogixfraudcall_callnow'] = "ໂທຕອນນີ້ເລີຍ!";
$_LANG['varilogixfraudcall_description'] = "ເພື່ອເປັນສ່ວນໜຶ່ງຂອງມາດຕະການປ້ອງກັນການສໍ້ໂກງ, ພວກເຮົາຈະໂທຫາເບີໂທລະສັບທີ່ລົງທະບຽນໄວ້ໃນບັນຊີຂອງທ່ານ ແລະ ຂໍໃຫ້ທ່ານປ້ອນລະຫັດ pin ຂ້າງເທິງ. ກະລຸນາຈົດລະຫັດ pin ໄວ້ ແລະ ເມື່ອທ່ານພ້ອມທີ່ຈະຮັບສາຍ, ກະລຸນາຄລິກທີ່ປຸ່ມຂ້າງລຸ່ມນີ້.";
$_LANG['varilogixfraudcall_error'] = "ເກີດຂໍ້ຜິດພາດ ແລະ ພວກເຮົາບໍ່ສາມາດໂທຫາເບີໂທລະສັບຂອງທ່ານເພື່ອຢືນຢັນຄຳສັ່ງຊື້ໄດ້. ກະລຸນາຕິດຕໍ່ພະແນກຊ່ວຍເຫຼືອຂອງພວກເຮົາໂດຍໄວທີ່ສຸດເພື່ອເຮັດໃຫ້ການສັ່ງຊື້ສຳເລັດ.";
$_LANG['varilogixfraudcall_fail'] = "ການໂທເພື່ອຢືນຢັນຄຳສັ່ງຊື້ຂອງທ່ານຫຼົ້ມເຫຼວ. ນີ້ອາດຈະເປັນຍ້ອນເບີໂທລະສັບຂອງທ່ານບໍ່ຖືກຕ້ອງ ຫຼື ຖືກບັນຊີດຳໃນລະບົບຂອງພວກເຮົາ. ກະລຸນາຕິດຕໍ່ພະແນກຊ່ວຍເຫຼືອຂອງພວກເຮົາໂດຍໄວທີ່ສຸດເພື່ອເຮັດໃຫ້ການສັ່ງຊື້ສຳເລັດ.";
