$_LANG['promoappliedbutnodiscount'] = "ລະຫັດໂປຣໂມຊັ່ນທີ່ທ່ານປ້ອນໄດ້ຖືກໃຊ້ໃນລົດເຂັນແລ້ວ ແຕ່ຍັງບໍ່ມີລາຍການໃດທີ່ກົງກັບເງື່ອນໄຂສ່ວນຫຼຸດ - ກະລຸນາກວດສອບເງື່ອນໄຂໂປຣໂມຊັ່ນ";

$_LANG['upgradeerroroverdueinvoice'] = "ທ່ານບໍ່ສາມາດອັບເກຣດ ຫຼື ດາວເກຣດສິນຄ້ານີ້ໄດ້ໃນເວລານີ້ ເນື່ອງຈາກໃບແຈ້ງໜີ້ສຳລັບການຕໍ່ອາຍຸຮອບຖັດໄປໄດ້ຖືກສ້າງຂຶ້ນແລ້ວ.<br /><br />ເພື່ອດຳເນີນການຕໍ່, ກະລຸນາຊຳລະໃບແຈ້ງໜີ້ທີ່ຄ້າງຢູ່ນັ້ນກ່ອນ ຫຼັງຈາກນັ້ນທ່ານຈຶ່ງຈະສາມາດອັບເກຣດ ຫຼື ດາວເກຣດໄດ້ທັນທີ ແລະ ຈະມີການເກັບສ່ວນຕ່າງ ຫຼື ຄືນເງິນຕາມຄວາມເໝາະສົມ.";
$_LANG['upgradeexistingupgradeinvoice'] = "ທ່ານບໍ່ສາມາດອັບເກຣດ ຫຼື ດາວເກຣດສິນຄ້ານີ້ໄດ້ໃນເວລານີ້ ເນື່ອງຈາກມີການອັບເກຣດ ຫຼື ດາວເກຣດທີ່ກຳລັງດຳເນີນການຢູ່.<br /><br />ເພື່ອດຳເນີນການຕໍ່, ກະລຸນາຊຳລະໃບແຈ້ງໜີ້ທີ່ຄ້າງຢູ່ນັ້ນກ່ອນ ຫຼັງຈາກນັ້ນທ່ານຈຶ່ງຈະສາມາດອັບເກຣດ ຫຼື ດາວເກຣດໄດ້ທັນທີ ແລະ ຈະມີການເກັບສ່ວນຕ່າງ ຫຼື ຄືນເງິນຕາມຄວາມເໝາະສົມ.<br/><br/>ຫາກທ່ານຄິດວ່າໄດ້ຮັບຂໍ້ຄວາມນີ້ຍ້ອນຄວາມຜິດພາດ, ກະລຸນາສົ່ງປີ້ແຈ້ງບັນຫາ.";

