$_LANG['domaincannotbemanaged'] = "ບໍ່ສາມາດຈັດການໂດຍອັດຕະໂນມັດໄດ້ - ກະລຸນາຕິດຕໍ່ຝ່າຍສະໜັບສະໜູນກ່ຽວກັບການປ່ຽນແປງໃດໆທີ່ທ່ານຕ້ອງການເຮັດ";
$_LANG['domainbulkmanagementnotpossible'] = "ໜ້າເສຍດາຍທີ່ການຕັ້ງຄ່າເຫຼົ່ານີ້ບໍ່ສາມາດແກ້ໄຂໄດ້ຈາກພື້ນທີ່ລູກຄ້າໃນເວລານີ້. ກະລຸນາຕິດຕໍ່ຝ່າຍສະໜັບສະໜູນກ່ຽວກັບການປ່ຽນແປງໃດໆທີ່ທ່ານຕ້ອງການເຮັດ.";

