$_LANG['domainautorenewinfo'] = "ການຕໍ່ອາຍຸອັດຕະໂນມັດຊ່ວຍປົກປ້ອງໂດເມນຂອງທ່ານ. ເມື່ອເປີດໃຊ້ງານ, ພວກເຮົາຈະສົ່ງໃບແຈ້ງໜີ້ການຕໍ່ອາຍຸໃຫ້ທ່ານໂດຍອັດຕະໂນມັດສອງສາມອາທິດກ່ອນທີ່ໂດເມນຂອງທ່ານຈະໝົດອາຍຸ, ແລະ ຈະຕໍ່ອາຍຸໂດເມນໃຫ້ຫາກການຊຳລະເງິນສຳເລັດ.";
