$_LANG['affiliatesignupinfo2'] = "ພວກເຮົາຕິດຕາມຜູ້ເຂົ້າຊົມທີ່ທ່ານແນະນຳໂດຍໃຊ້ cookies, ດັ່ງນັ້ນຜູ້ໃຊ້ທີ່ທ່ານແນະນຳບໍ່ຈຳເປັນຕ້ອງຊື້ທັນທີເພື່ອໃຫ້ທ່ານໄດ້ຮັບຄ່າຄອມມິດຊັ່ນ. Cookies ຈະມີອາຍຸການໃຊ້ງານເຖິງ 90 ວັນຫຼັງຈາກການເຂົ້າຊົມຄັ້ງທຳອິດ.";
$_LANG['affiliatesignupinfo3'] = "ຖ້າທ່ານຕ້ອງການຮູ້ຂໍ້ມູນເພີ່ມເຕີມ, ກະລຸນາຕິດຕໍ່ພວກເຮົາ.";

