$_LANG['twofaenforced'] = "ເພື່ອຄວາມປອດໄພຂອງທ່ານ, ພວກເຮົາຮຽກຮ້ອງໃຫ້ທ່ານຕ້ອງເປີດໃຊ້ການຢືນຢັນຕົວຕົນສອງຊັ້ນກ່ອນທີ່ຈະສາມາດດຳເນີນການຕໍ່ໄດ້. ໜ້ານີ້ຈະແນະນຳທ່ານຜ່ານຂັ້ນຕອນການຕັ້ງຄ່າ.";
$_LANG['twofasetup'] = "ຂັ້ນຕອນການຕັ້ງຄ່າການຢືນຢັນຕົວຕົນສອງຊັ້ນ";
$_LANG['twofasetupgetstarted'] = "ເລີ່ມຕົ້ນ";
$_LANG['twofaactivationintro'] = "ການຢືນຢັນຕົວຕົນສອງຊັ້ນຈະເພີ່ມການປົກປ້ອງອີກຊັ້ນໜຶ່ງໃນການເຂົ້າສູ່ລະບົບ. ເມື່ອເປີດໃຊ້ ແລະ ຕັ້ງຄ່າແລ້ວ, ທຸກໆຄັ້ງທີ່ທ່ານເຂົ້າສູ່ລະບົບ ທ່ານຈະຖືກຖາມໃຫ້ປ້ອນທັງຊື່ຜູ້ໃຊ້ ແລະ ລະຫັດຜ່ານ ພ້ອມກັບປັດໄຈທີສອງ ເຊັ່ນ ລະຫັດຄວາມປອດໄພ.";
$_LANG['twofaactivationmultichoice'] = "ເພື່ອດຳເນີນການຕໍ່, ກະລຸນາເລືອກວິທີການຢືນຢັນຕົວຕົນສອງຊັ້ນທີ່ທ່ານຕ້ອງການຈາກຂ້າງລຸ່ມນີ້.";
$_LANG['twofadisableintro'] = "ເພື່ອປິດໃຊ້ງານການຢືນຢັນຕົວຕົນສອງຊັ້ນ ກະລຸນາຢືນຢັນລະຫັດຜ່ານຂອງທ່ານໃນຊ່ອງຂ້າງລຸ່ມນີ້.";
