$_LANG['twofamoduleerror'] = "ມີຂໍ້ຜິດພາດເກີດຂຶ້ນໃນການໂຫຼດໂມດູນ. ກະລຸນາລອງໃໝ່.";
$_LANG['twofaactivationcomplete'] = "ການຕັ້ງຄ່າການຢືນຢັນຕົວຕົນສອງຊັ້ນສຳເລັດແລ້ວ!";
$_LANG['twofadisableconfirmation'] = "ການຢືນຢັນຕົວຕົນສອງຊັ້ນຖືກປິດໃຊ້ງານສຳລັບບັນຊີຂອງທ່ານແລ້ວ.";
