$_LANG['twoiptimebasedpassword'] = "ລະຫັດຜ່ານຄັ້ງດຽວແບບກຳນົດເວລາ (TOTP)";
$_LANG['twoiptimebasedexplain'] = "ຕົວເລືອກການຢືນຢັນຕົວຕົນນີ້ໄດ້ຮັບປັດໄຈທີສອງໂດຍໃຊ້ລະບົບກຳນົດເວລາ. ໂທລະສັບມືຖືຂອງທ່ານສາມາດໃຊ້ເພື່ອສ້າງລະຫັດໄດ້. ຖ້າທ່ານຍັງບໍ່ມີແອັບທີ່ສາມາດເຮັດສິ່ງນີ້ໄດ້, ພວກເຮົາແນະນຳ Google Authenticator ເຊິ່ງມີໃຫ້ສຳລັບອຸປະກອນມືຖື iOS, Android ແລະ Windows.";
