$_LANG['twoipconfigurestep2'] = "ຈາກນັ້ນໃຊ້ແອັບຂອງທ່ານເພື່ອສະແກນບາໂຄດຂ້າງລຸ່ມນີ້, ຫຼື ປ້ອນລະຫັດລັບນີ້ດ້ວຍຕົນເອງ: ";
