$_LANG['cloudSlider']['feature01Title'] = "ໄລຍະເວລາການໃຊ້ງານເຊີເວີສູງສຸດ";
$_LANG['cloudSlider']['feature01Description'] = "ໄລຍະເວລາການໃຊ້ງານເຊີເວີ (Uptime) ເປັນສິ່ງສຳຄັນສຳລັບທຸກທຸລະກິດ. ເຊີເວີໄຟລ໌, ຖານຂໍ້ມູນ, ອີເມລ ແລະ ເວັບເຊີເວີ ເປັນສ່ວນໜຶ່ງທີ່ຂາດບໍ່ໄດ້ໃນຂະບວນການທຸລະກິດ. ນັ້ນແມ່ນເຫດຜົນທີ່ພວກເຮົາໃຫ້ຄວາມສຳຄັນກັບການຮັບປະກັນ Uptime ສູງສຸດ.";
$_LANG['cloudSlider']['feature01DescriptionTwo'] = "ໂດຍການໄວ້ວາງໃຈໃຫ້ພວກເຮົາເບິ່ງແຍງທຸລະກິດຂອງທ່ານ, ພວກເຮົາສັນຍາວ່າຈະມີ Uptime 99.9% ໃນການບໍລິການທັງໝົດຂອງພວກເຮົາ.";
$_LANG['cloudSlider']['feature02Title'] = "ການສົ່ງຂໍ້ມູນທົ່ວໂລກ";
$_LANG['cloudSlider']['feature02Description'] = "ການບໍລິການຂອງພວກເຮົາຂັບເຄື່ອນດ້ວຍເຊີເວີ ແລະ ສູນຂໍ້ມູນຫຼາຍຮ້ອຍແຫ່ງທົ່ວໂລກ, ທ່ານຈຶ່ງໝັ້ນໃຈໄດ້ວ່າລູກຄ້າຈະສາມາດເຂົ້າເຖິງເວັບໄຊຂອງທ່ານໄດ້ຈາກທຸກຫົນທຸກແຫ່ງ.";
$_LANG['cloudSlider']['feature02DescriptionTwo'] = "ຄວາມຕັ້ງໃຈໃນການຊ່ວຍເຫຼືອລູກຄ້າຂອງພວກເຮົາມີຢູ່ທົ່ວໂລກເຊັ່ນກັນ. ພວກເຮົາພ້ອມຊ່ວຍເຫຼືອທ່ານຜ່ານທາງໂທລະສັບ, ອີເມລ ຫຼື ແຊັດສົດ.";
$_LANG['cloudSlider']['feature03Title'] = "ຄວາມປອດໄພລະດັບສູງ";
$_LANG['cloudSlider']['feature03Description'] = "ອຸ່ນໃຈດ້ວຍການຕິດຕາມຄວາມປອດໄພຕະຫຼອດ 24 ຊົ່ວໂມງ ແລະ ການປ້ອງກັນ DDoS. ທ່ານໃຫ້ຄວາມສຳຄັນກັບການປົກປ້ອງຂໍ້ມູນລູກຄ້າ, ພວກເຮົາກໍ່ເຊັ່ນກັນ.";
$_LANG['cloudSlider']['feature03DescriptionTwo'] = "ພວກເຮົາມີເຄື່ອງມືຄວາມປອດໄພຫຼາກຫຼາຍໃຫ້ທ່ານເລືອກໃຊ້ ເຊັ່ນ SSL certificates, ການຕັ້ງຄ່າ Firewall, ການຕິດຕາມຄວາມປອດໄພ, ການເຂົ້າເຖິງ VPN ແລະ ອື່ນໆ.";
$_LANG['cloudSlider']['selectProductLevel'] = "ເລືອກລະດັບທີ່ເໝາະສົມທີ່ສຸດສຳລັບທ່ານ!";

