$_LANG['store']['ssl']['dv']['tagline'] = "ປົກປ້ອງເວັບໄຊຂອງທ່ານພາຍໃນບໍ່ເທົ່າໃດນາທີ!";
$_LANG['store']['ssl']['dv']['descriptionTitle'] = "Standard DV SSL ແມ່ນຫຍັງ?";
$_LANG['store']['ssl']['dv']['descriptionContent'] = "<p>ໃບຢັ້ງຢືນແບບ Domain Validation (DV) ເປັນວິທີທີ່ປະຢັດ ແລະ ວ່ອງໄວໃນການຕິດຕັ້ງ SSL ໃຫ້ກັບເວັບໄຊຂອງທ່ານ. ໃບຢັ້ງຢືນປະເພດນີ້ຈະກວດສອບຄວາມເປັນເຈົ້າຂອງໂດເມນເທົ່ານັ້ນ, ໂດຍບໍ່ມີການກວດສອບໃນລະດັບອົງກອນເພີ່ມເຕີມ.</p><p>ໃບຢັ້ງຢືນ DV ເໝາະສຳລັບເວັບໄຊສ່ວນຕົວ, ບລັອກ ແລະ ໂຊຊຽວມີເດຍ ຫຼື ເວັບໄຊທີ່ບໍ່ມີການສົ່ງຂໍ້ມູນສ່ວນຕົວທີ່ສຳຄັນ. ໃບຢັ້ງຢືນ DV ຈະສະແດງຮູບກະແຈໃນບຣາວເຊີ ແລະ ເປີດໃຊ້ງານ https ເພື່ອໃຫ້ຜູ້ເຂົ້າຊົມ ແລະ ລູກຄ້າໝັ້ນໃຈວ່າທ່ານໃຫ້ຄວາມສຳຄັນກັບຄວາມເປັນສ່ວນຕົວຂອງພວກເຂົາ.</p>";

$_LANG['store']['ssl']['ov']['tagline'] = "SSL ຄວາມປອດໄພສູງທີ່ສະແດງຕົວຕົນທີ່ໄດ້ຮັບການຢືນຢັນຂອງເວັບໄຊໃຫ້ຜູ້ເຂົ້າຊົມເຫັນ";
$_LANG['store']['ssl']['ov']['descriptionTitle'] = "Organization Validation SSL ແມ່ນຫຍັງ?";
$_LANG['store']['ssl']['ov']['descriptionContent'] = "<p>ໃບຢັ້ງຢືນ SSL ແບບ Organization Validated (OV) ໃຫ້ການຢືນຢັນຕົວຕົນທັນທີ ແລະ ການປົກປ້ອງ SSL ທີ່ແຂງແຮງສຳລັບເວັບໄຊ ແລະ ທຸລະກິດຂອງທ່ານ.</p><p>OV SSL ເປັນໃບຢັ້ງຢືນທີ່ຜ່ານການກວດສອບອົງກອນ ເຊິ່ງຊ່ວຍເພີ່ມຄວາມໜ້າເຊື່ອຖືໃຫ້ກັບເວັບໄຊຂອງທ່ານຫຼາຍກວ່າ SSL ແບບ DV. ມັນຈະສະແດງຮູບກະແຈ ແລະ https, ສະແດງຂໍ້ມູນອົງກອນຂອງທ່ານ ແລະ ເຮັດໃຫ້ລູກຄ້າໝັ້ນໃຈວ່າທ່ານໃຫ້ຄວາມສຳຄັນກັບຄວາມປອດໄພຢ່າງສູງ. ຜູ້ເຂົ້າຊົມສາມາດກວດສອບໄດ້ວ່າເວັບໄຊນີ້ດຳເນີນການໂດຍບໍລິສັດທີ່ຖືກຕ້ອງຕາມກົດໝາຍ ແລະ ບໍ່ແມ່ນເວັບໄຊປອມແປງ.</p>";

$_LANG['store']['ssl']['ev']['tagline'] = "ເປີດໃຊ້ແຖບທີ່ຢູ່ສີຂຽວເພື່ອຄວາມໄວ້ວາງໃຈ ແລະ ອັດຕາການຊື້ທີ່ສູງທີ່ສຸດ";
$_LANG['store']['ssl']['ev']['descriptionTitle'] = "Extended Validation SSL ແມ່ນຫຍັງ?";
$_LANG['store']['ssl']['ev']['descriptionContent'] = "<p>EV SSL ແມ່ນໃບຢັ້ງຢືນແບບ Extended Validation ເຊິ່ງເປັນລະດັບ SSL ທີ່ສູງທີ່ສຸດທີ່ມີໃນປະຈຸບັນ ແລະ ໃຫ້ຄວາມໜ້າເຊື່ອຖື ແລະ ຄວາມໄວ້ວາງໃຈສູງສຸດແກ່ເວັບໄຊຂອງທ່ານ ເມື່ອທຽບກັບ SSL ແບບ OV ຫຼື DV.</p><p>Extended Validation SSL ຈະສະແດງແຖບທີ່ຢູ່ສີຂຽວ ແລະ ສະແດງຊື່ບໍລິສັດ ຫຼື ອົງກອນຂອງທ່ານໃນແຖບທີ່ຢູ່ຂອງບຣາວເຊີ. ສັນຍາລັກຄວາມປອດໄພທີ່ຊັດເຈນເຫຼົ່ານີ້ຈະເຮັດໃຫ້ຜູ້ເຂົ້າຊົມຮູ້ວ່າມີການກວດສອບຢ່າງເຂັ້ມງວດເພື່ອຢືນຢັນເວັບໄຊທີ່ພວກເຂົາກຳລັງເຂົ້າເບິ່ງ, ເພີ່ມຄວາມໝັ້ນໃຈໃຫ້ແກ່ຜູ້ໃຊ້ – ນີ້ຄືເຫດຜົນທີ່ບໍລິສັດ ແລະ ອົງກອນຂະໜາດໃຫຍ່ສ່ວນໃຫຍ່ເລືອກໃຊ້ໃບຢັ້ງຢືນ EV.</p>";

$_LANG['store']['ssl']['wildcard']['tagline'] = "ປົກປ້ອງໂດເມນຍ່ອຍ (Subdomains) ບໍ່ຈຳກັດດ້ວຍໃບຢັ້ງຢືນດຽວ.";
$_LANG['store']['ssl']['wildcard']['descriptionTitle'] = "Wildcard SSL Certificate ແມ່ນຫຍັງ?";
$_LANG['store']['ssl']['wildcard']['descriptionContent'] = "<p>Wildcard SSL ຊ່ວຍໃຫ້ທ່ານສາມາດປົກປ້ອງໂດເມນຍ່ອຍໄດ້ບໍ່ຈຳກັດຈຳນວນດ້ວຍໃບຢັ້ງຢືນພຽງໃບດຽວ. ມັນເປັນທາງອອກທີ່ດີເລີດສຳລັບໃຜກໍ່ຕາມທີ່ເບິ່ງແຍງຫຼາຍເວັບໄຊ ຫຼື ຫຼາຍໜ້າທີ່ຢູ່ພາຍໃຕ້ໂດເມນດຽວກັນ. ຄ່າໃຊ້ຈ່າຍຄັ້ງດຽວຂອງໃບຢັ້ງຢືນຈະຄຸ້ມຄອງລວມໄປເຖິງໂດເມນຍ່ອຍທີ່ທ່ານອາດຈະເພີ່ມຂຶ້ນໃນອະນາຄົດ.</p><p>ຕ່າງຈາກໃບຢັ້ງຢືນ SSL ມາດຕະຖານທີ່ອອກໃຫ້ສຳລັບຊື່ໂດເມນດຽວເທົ່ານັ້ນ ເຊັ່ນ www.yourdomain.com, ເຊິ່ງໝາຍຄວາມວ່າມັນສາມາດໃຊ້ໄດ້ສະເພາະກັບໂດເມນນັ້ນ, ແຕ່ໃບຢັ້ງຢືນ Wildcard SSL ຈະອອກໃຫ້ໃນຮູບແບບ *.yourdomain.com, ໂດຍເຄື່ອງໝາຍດາວ (*) ໝາຍເຖິງໂດເມນຍ່ອຍທັງໝົດທີ່ເປັນໄປໄດ້.</p><p>Wildcard SSL ມີໃຫ້ເລືອກທັງໃນແບບ DV ແລະ OV SSL.</p>";

$_LANG['store']['websiteBuilder']['headline'] = "ການສ້າງເວັບໄຊຈະບໍ່ແມ່ນເລື່ອງຍາກອີກຕໍ່ໄປ";
