$_LANG['store']['websiteBuilder']['introduction'] = "ເຄື່ອງມືສ້າງເວັບໄຊແບບລາກ ແລະ ວາງຂອງ Weebly ຊ່ວຍໃຫ້ການສ້າງເວັບໄຊທີ່ເປັນມືອາຊີບ ແລະ ມີປະສິດທິພາບເປັນເລື່ອງງ່າຍ ໂດຍບໍ່ຈຳເປັນຕ້ອງມີທັກສະທາງເຕັກນິກ. ຜູ້ປະກອບການ ແລະ ທຸລະກິດຂະໜາດນ້ອຍກວ່າ 40 ລ້ານລາຍໄດ້ເລືອກໃຊ້ Weebly ເພື່ອສ້າງຕົວຕົນໃນໂລກອອນລາຍດ້ວຍເວັບໄຊ, ບລັອກ ຫຼື ຮ້ານຄ້າ.";

