$_LANG['remoteAuthn']['oneTimeAuthRequired'] = 'ກະລຸນາລົງຊື່ເຂົ້າໃຊ້ໃຫ້ສຳເລັດເພື່ອເຊື່ອມໂຍງບໍລິການນີ້ກັບບັນຊີທີ່ມີຢູ່ຂອງທ່ານ. ທ່ານຈະເຮັດຂັ້ນຕອນນີ້ພຽງແຕ່ຄັ້ງດຽວ.';
