$_LANG['remoteAuthn']['completeNewAccountForm'] = 'ກະລຸນາຕື່ມຂໍ້ມູນບັນຊີໃໝ່ຂອງທ່ານໃຫ້ຄົບຖ້ວນ.';
$_LANG['remoteAuthn']['linkedToAnotherClient'] = 'ບັນຊີນີ້ຖືກເຊື່ອມຕໍ່ກັບບັນຊີອື່ນໃນລະບົບຂອງພວກເຮົາແລ້ວ. ກະລຸນາເລືອກບັນຊີອື່ນຈາກຜູ້ໃຫ້ບໍລິການຢືນຢັນຕົວຕົນພາຍນອກ.';
$_LANG['remoteAuthn']['alreadyLinkedToYou'] = 'ບັນຊີນີ້ຖືກເຊື່ອມຕໍ່ກັບບັນຊີຂອງທ່ານແລ້ວ. ກະລຸນາເລືອກບັນຊີອື່ນຈາກຜູ້ໃຫ້ບໍລິການຢືນຢັນຕົວຕົນພາຍນອກ.';
