$_LANG['domains']['changePending'] = "ຄຳຂໍປ່ຽນແປງຂອງທ່ານໄດ້ກະຕຸ້ນຂະບວນການຢືນຢັນຂໍ້ມູນຜູ້ຕິດຕໍ່. ອີເມລຢືນຢັນຄວາມເປັນເຈົ້າຂອງໄດ້ຖືກສົ່ງຫາ :email ແລ້ວ. ຄລິກທີ່ລິງໃນອີເມລເພື່ອຢືນຢັນການປ່ຽນແປງ.";
$_LANG['domains']['changePendingDate'] = "ຄຳຂໍປ່ຽນແປງຂອງທ່ານໄດ້ກະຕຸ້ນຂະບວນການຢືນຢັນຂໍ້ມູນຜູ້ຕິດຕໍ່. ອີເມລຢືນຢັນຄວາມເປັນເຈົ້າຂອງໄດ້ຖືກສົ່ງຫາ :email ແລ້ວ. ຄລິກທີ່ລິງໃນອີເມລພາຍໃນ :days ວັນ ເພື່ອຢືນຢັນການປ່ຽນແປງ.";
$_LANG['domains']['changePendingFormRequired'] = "ການປ່ຽນແປງຂໍ້ມູນຜູ້ຈົດທະບຽນຂອງທ່ານຖືກສົ່ງສຳເລັດແລ້ວ. ເພື່ອໃຫ້ຂະບວນການສຳເລັດ, ທ່ານຈຳເປັນຕ້ອງຕື່ມແບບຟອມ <strong>Change of Registrant</strong>. ກະລຸນາເຂົ້າໄປທີ່ :form, ຕື່ມຂໍ້ມູນຕາມຄຳແນະນຳ ແລະ ສົ່ງກັບຄືນຫາພວກເຮົາ.";

