$_LANG['fraud']['manualReview'] = "ຄຳສັ່ງຊື້ຂອງທ່ານຖືກລະງັບໄວ້ເພື່ອລໍຖ້າການກວດສອບດ້ວຍມື.<br /><br />ຫາກທ່ານຄິດວ່າຂໍ້ຄວາມນີ້ເກີດຈາກຄວາມຜິດພາດ, ກະລຸນາ <a href=\"submitticket.php\">ສົ່ງຄຳຮ້ອງ (Ticket)</a> ຫາທີມງານບໍລິການລູກຄ້າຂອງພວກເຮົາ. ຂອບໃຈ.";
$_LANG['fraud']['highFraudRiskScore'] = "ຄຳສັ່ງຊື້ຂອງທ່ານຖືກໝາຍວ່າເປັນວົງເງິນທີ່ມີຄວາມສ່ຽງສູງ ແລະ ຖືກລະງັບໄວ້ເພື່ອລໍຖ້າການກວດສອບດ້ວຍມື.<br /><br />ຫາກທ່ານຄິດວ່າຂໍ້ຄວາມນີ້ເກີດຈາກຄວາມຜິດພາດ, ກະລຸນາ <a href=\"submitticket.php\">ສົ່ງຄຳຮ້ອງ (Ticket)</a> ຫາທີມງານບໍລິການລູກຄ້າຂອງພວກເຮົາ. ຂອບໃຈ.";
$_LANG['fraud']['countryMismatch'] = "ປະເທດຂອງທີ່ຢູ່ IP ຂອງທ່ານບໍ່ກົງກັບປະເທດໃນທີ່ຢູ່ການຊຳລະເງິນທີ່ທ່ານປ້ອນ, ດັ່ງນັ້ນພວກເຮົາຈຶ່ງບໍ່ສາມາດຮັບຄຳສັ່ງຊື້ຂອງທ່ານໄດ້";
$_LANG['fraud']['highRiskCountry'] = "ຂໍອະໄພ, ພວກເຮົາບໍ່ສາມາດຮັບຄຳສັ່ງຊື້ຂອງທ່ານໄດ້ ເນື່ອງຈາກມີກິດຈະກຳທີ່ສໍ້ໂກງຫຼາຍຈາກປະເທດຂອງທ່ານ. ຫາກທ່ານຕ້ອງການຊຳລະດ້ວຍວິທີອື່ນ, ກະລຸນາຕິດຕໍ່ພວກເຮົາ.";
