$_LANG['store']['codeGuard']['faq']['title'] = "ຄຳຖາມທີ່ພົບເລື້ອຍ";
$_LANG['store']['codeGuard']['faq']['q1'] = "CodeGuard ແມ່ນຫຍັງ?";
$_LANG['store']['codeGuard']['faq']['a1'] = "CodeGuard ເປັນບໍລິການສຳຮອງຂໍ້ມູນເວັບໄຊແບບອັດຕະໂນມັດເຕັມຮູບແບບ ທີ່ໃຫ້ການປົກປ້ອງການສູນເສຍຂໍ້ມູນ ແລະ ມັນແວຢ່າງຄົບຖ້ວນ.";
$_LANG['store']['codeGuard']['faq']['q2'] = "ເປັນຫຍັງຂ້ອຍຈຶ່ງຕ້ອງການ CodeGuard?";
$_LANG['store']['codeGuard']['faq']['a2'] = "CodeGuard ໃຫ້ບໍລິການສຳຮອງຂໍ້ມູນພາຍນອກທີ່ເປັນອິດສະຫຼະ ພ້ອມກັບການຕິດຕາມທຸກມື້ເພື່ອຮັບປະກັນວ່າເວັບໄຊຂອງທ່ານຈະອອນລາຍ ແລະ ປອດຈາກມັນແວ.";
$_LANG['store']['codeGuard']['faq']['q3'] = "ມັນເຮັດວຽກແນວໃດ?";
$_LANG['store']['codeGuard']['faq']['a3'] = "CodeGuard ຈະທຳການ Snapshot ເວັບໄຊຂອງທ່ານໂດຍອັດຕະໂນມັດທຸກມື້. ທ່ານສາມາດໃຊ້ Snapshot ເຫຼົ່ານີ້ເພື່ອຄືນຄ່າທັງໝົດເວັບໄຊ ຫຼື ໄຟລ໌ສະເພາະໃຫ້ເປັນເວີຊັນກ່ອນໜ້າໄດ້ທຸກເວລາ.";
$_LANG['store']['codeGuard']['faq']['q4'] = "ຈະເກີດຫຍັງຂຶ້ນຫາກພື້ນທີ່ຈັດເກັບຂໍ້ມູນໝົດ?";
$_LANG['store']['codeGuard']['faq']['a4'] = "ການປ່ຽນແຜນນັ້ນງ່າຍຫຼາຍ! ທ່ານສາມາດອັບເກຣດ ແລະ ເພີ່ມພື້ນທີ່ຈັດເກັບຂໍ້ມູນໄດ້ໃນບໍ່ເທົ່າໃດຄລິກຜ່ານ Client Area ຂອງພວກເຮົາ.";
$_LANG['store']['codeGuard']['faq']['q5'] = "ຂໍ້ມູນສຳຮອງຖືກເກັບໄວ້ຢູ່ໃສ?";
$_LANG['store']['codeGuard']['faq']['a5'] = "ຂໍ້ມູນສຳຮອງຖືກເກັບໄວ້ໃນ Amazon Web Services Simple Storage System ເຊິ່ງໃຫ້ຄວາມປອດໄພ ແລະ ຄວາມໝັ້ນຄົງລະດັບແຖວໜ້າຂອງຕະຫຼາດ.";
